        item.pos = null;
        item.carriedBy = s.id;
        item.reservedBy = null;
        Js.SetProp(s, slot, item.id);
        s.note = (item.kind == "cart") ? "took a cart for hauling" : ((slot == "tool") ? $"took a {Js.Str(item.kind)}" : $"put on {Js.Str(item.kind)}");
        return true;
    }

    /// <summary>Gives up the reserved garment or cloth (if any). Safe to call when not dressing.</summary>
    public static void cancelDressing(SimState state, Survivor s, string note)
    {
        if (!Js.T(s.dressing))
        {
            return;
        }
        var item = Items.getItem(state, s.dressing);
        if (Js.T(item) && (item.reservedBy == s.id))
        {
            item.reservedBy = null;
        }
        s.dressing = null;
        s.goal = null;
        s.path = [];
        s.pathVersion = -1;
        s.note = note;
    }

    /// <summary>Drops the plan if the item went away between ticks.</summary>
